      req.destroy = () => {
        req.destroyed = true;
      };
      req.close = req.destroy;
      req.end = () => {
        const res = new PassThrough();
        res.statusCode = 200;
        res.statusMessage = 'OK';
        res.headers = { 'content-type': 'application/json' };
        res.req = req;
        onResponse(res);
        res.end(responseBody ? responseBody : '{"value":"ok"}');
      };

      return req;
    },
  };

  return {
    transport,
    getCalls: () => calls,
  };
};

const createProgressTransport = (config) => {
  const opts = config || {};
  const responseChunks = opts.responseChunks || ['ok'];
  const responseHeaders = opts.responseHeaders || {};

  return {
    request(_options, onResponse) {
      const req = new Writable({
        write(_chunk, _encoding, callback) {
          callback();
        },
      });

      req.destroyed = false;
      req.setTimeout = () => {};
      req.close = () => {
        req.destroyed = true;
      };

      const originalDestroy = req.destroy.bind(req);
      req.destroy = (...args) => {
        req.destroyed = true;
        return originalDestroy(...args);
      };

      const originalEnd = req.end.bind(req);
      req.end = (...args) => {
        originalEnd(...args);

        const res = new PassThrough();
        res.statusCode = 200;
        res.statusMessage = 'OK';
        res.headers = Object.assign(
          {
            'content-type': 'text/plain',
          },
          responseHeaders
        );
        res.req = req;

        onResponse(res);

        responseChunks.forEach((chunk) => {
          res.write(chunk);
        });
        res.end();
      };

      return req;
    },
  };
};

