const createTransport = (config) => {
  const opts = config || {};

  return {
    request(_options, onResponse) {
      const req = new EventEmitter();
      req.destroyed = false;
      req._timeoutCallback = null;

      req.setTimeout = (_ms, callback) => {
        req._timeoutCallback = callback;
      };

      req.write = () => true;

      req.destroy = () => {
        req.destroyed = true;
      };
      req.close = req.destroy;

      req.end = () => {
        if (opts.triggerTimeout && req._timeoutCallback) {
          req._timeoutCallback();
          return;
        }

        const res = new PassThrough();
        res.statusCode = 200;
        res.statusMessage = 'OK';
        res.headers = { 'content-type': 'application/json' };
        res.req = req;

        onResponse(res);
        res.end(opts.body === undefined ? '{"ok":true}' : opts.body);
      };

      return req;
    },
  };
};

const createEchoTransport = () => {
  let capturedOptions;

  const transport = {
    request(options, onResponse) {
      capturedOptions = options;
      const chunks = [];

      const req = new EventEmitter();
      req.destroyed = false;
      req.setTimeout = () => {};
      req.destroy = () => {
        req.destroyed = true;
      };
      req.close = req.destroy;
      req.write = (chunk) => {
        chunks.push(Buffer.from(chunk));
        return true;
      };
      req.end = (chunk) => {
        if (chunk) {
          chunks.push(Buffer.from(chunk));
        }

        const res = new PassThrough();
        res.statusCode = 200;
        res.statusMessage = 'OK';
        res.headers = { 'content-type': 'application/json' };
        res.req = req;
        onResponse(res);
        res.end(
          JSON.stringify({
            path: options.path,
            body: Buffer.concat(chunks).toString('utf8'),
            contentType:
              options.headers &&
              (options.headers['Content-Type'] || options.headers['content-type']),
          })
        );
      };

      return req;
    },
  };

  return {
    transport,
    getCapturedOptions: () => capturedOptions,
  };
};

