 body {
   margin: 0;
   font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
   background: var(--bg-color);
   color: var(--text-color);
 }

 pre {
   min-height: 39px;
   white-space: pre-wrap;
   /* wrap long lines instead of stretching the panel */
   word-wrap: break-word;
   overflow: auto;
 }

 .box {
   display: grid;
   grid-template-columns: 1fr 1fr;
   grid-gap: 40px;
   /* Increased gap between input and response columns */
 }

 .response {
   min-width: 0;
   /* prevents content overflow from pushing layout */
   overflow-x: auto;
 }

 .header {
   display: flex;
   flex-direction: row;
   justify-content: space-between;
   align-items: center;
   margin-bottom: 2rem;
   /* Added space below the header */
 }

 /* 
Input & Well Styles
 */
 .well,
 .form-control {

   background: var(--well-bg);
   margin-top: 5px;
   border: 1px solid var(--border-color);
   border-radius: 16px;
   padding: 14px 16px;
   box-shadow: 0 10px 25px -8px var(--shadow-color);
   backdrop-filter: var(--glass-blur);
   /* glass effect */
 }

 .form-control {
   background: var(--input-bg);
   color: var(--text-color);
   border-radius: 16px;
   box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
   outline: none;
   /* remove default bootstrap focus outline */
 }

 .form-control::placeholder {
   color: #9e9eef;
   /* subtle placeholder */
 }

 /* Modern neon focus effect */
 .form-control:focus {
   background: var(--input-bg);
   /* keep consistent */
   border: 1px solid #ff00ff;
   /* neon border */
   box-shadow: 0 0 10px #ff00ff, 0 0 20px #00ffff;
   /* glowing focus */
   color: var(--text-color);
 }

 /* subtle placeholder fade on focus */
 .form-control:focus::placeholder {
   color: #ddd;
 }

 /* spacing between form groups */
 .form-group {
   margin-bottom: 1.75rem;
 }

 /* 
Header & Box Layout
 */
 .header {
   display: flex;

   flex-wrap: wrap;
   justify-content: space-between;
   align-items: center;
   margin-bottom: 2.5rem;
   gap: 15px;
 }

 .box {
   display: grid;
   grid-template-columns: 1fr 1fr;
   gap: 40px;
 }

 /* 
Theme Toggle Button
 */
 #theme-toggle {
   padding: 8px 18px;
   border-radius: 12px;
   border: none;
   cursor: pointer;
   background: var(--primary-gradient);
   color: #fff;
   font-weight: 600;
   box-shadow: 0 8px 20px -5px var(--shadow-color);
   transition: transform 0.25s ease, box-shadow 0.25s ease;
 }

 #theme-toggle:hover {
   transform: translateY(-3px);
   box-shadow: 0 12px 25px -8px var(--shadow-color);
 }

 /* 
Footer Styles
 */
 .footer {
   max-width: 900px;
   margin: 60px auto 40px auto;
   padding: 2.5rem 3rem;
   border-radius: 24px;
   background: var(--well-bg);
   box-shadow: 0 15px 35px -10px var(--shadow-color);
   display: flex;
   justify-content: space-between;
   align-items: center;
   flex-wrap: wrap;
   gap: 25px;
 }

 .footer-left {
   display: flex;
   flex-direction: column;
   gap: 6px;
 }

 .footer-left .footer-brand-axios,
 .footer-left .footer-brand-sandbox {
   font-size: 1.2em;
   font-weight: 700;
   background: var(--primary-gradient);
   background-clip: text;
   -webkit-background-clip: text;
   -webkit-text-fill-color: transparent;
 }

 .footer-left .footer-copyright {
   font-size: 0.9em;
   color: var(--footer-text-color);
 }

 .footer-nav ul {
   display: flex;
   gap: 25px;
   list-style: none;
   padding: 0;
   margin: 0;
   flex-wrap: wrap;
 }

 .footer-nav a {
   color: var(--footer-link-color);
   font-weight: 500;
   text-decoration: none;
   transition: color 0.3s ease, transform 0.2s ease;
 }

 .footer-nav a:hover {
   color: var(--footer-link-hover-color);
   transform: translateY(-2px);
   text-decoration: underline;
 }

 /* 
Buttons
 */
 .btn {
   padding: 10px 25px;
   border-radius: 50px;
   font-weight: 600;

      color: #fff;
      border: none;
      cursor: pointer;
      background: var(--primary-gradient);
      box-shadow: 0 10px 25px -8px var(--shadow-color);
      transition: all 0.3s ease;
    }

    .btn:hover {
      background: var(--btn-hover-gradient);
      transform: translateY(-3px);
      box-shadow: 0 14px 30px -10px var(--shadow-color);
    }

    /* 
   Code/Pre blocks
    */
    pre {
      border-radius: 16px;
      padding: 14px;
      background: var(--well-bg);
      box-shadow: inset 0 6px 12px -4px var(--shadow-color);
      overflow: auto;
    }

    /* 
   Responsive Layout
    */
    @media screen and (max-width: 1000px) {
      .box {
        grid-template-columns: 1fr;
      }
    }

    @media screen and (max-width: 768px) {
      .footer {
        flex-direction: column;
        text-align: center;
        padding: 2rem;
        max-width: 90%;
      }

      .footer-nav ul {
        justify-content: center;
      }
    }
  </style>
</head>

